def get(url):
 trail=[]
 try:
  req=Request(url,headers={'User-Agent':'Mozilla/5.0 scholarly-verification/1.0','Accept':'application/pdf,text/html;q=0.9,*/*;q=0.1'})
  with urlopen(req,timeout=35) as r:
   data=r.read(); final=r.geturl(); ct=r.headers.get('Content-Type','')
   trail.append({'url':url,'status':'ok','http_status':getattr(r,'status',200),'final_url':final,'content_type':ct,'bytes':len(data)})
   return data,final,ct,trail,None
 except Exception as e:
  trail.append({'url':url,'status':'error','error':type(e).__name__+': '+str(e)})
  return None,None,None,trail,str(e)

def text_of(data,ct):
 if not data:return ''
 if 'pdf' in (ct or '').lower() or data[:4]==b'%PDF':
  try:
   from pypdf import PdfReader
   import io
   r=PdfReader(io.BytesIO(data)); return '\\n'.join((x.extract_text() or '') for x in r.pages[:4])
  except Exception:return ''
 try:return data.decode('utf-8','ignore')
 except:return ''

def norm(s): return re.sub(r'[^a-z0-9]+',' ',s.lower()).strip()
rows=[]; downloads=[]; identities=[]; blocked=[]
for r in sel:
 pid=r['paper_id']; author,title,year,venue,url=M[pid]
 data,final,ct,trail,err=get(url)
 base={'paper_id':pid,'retained_citation':r['citation'],'expected_title':title,'expected_authors':author,'expected_year':year,'expected_venue':venue,'source_url':url,'resolution':'resolved' if data else 'blocked','final_url':final or '','retrieval_trail':trail}
 if data:
  ext='.pdf' if ('pdf' in (ct or '').lower() or data[:4]==b'%PDF') else '.html'
  fn=pid.replace('/','_')+ext; path=EVID/fn; path.write_bytes(data)
  sha=hashlib.sha256(data).hexdigest(); txt=text_of(data,ct); nt=norm(txt); ntit=norm(title)
  title_tokens=[x for x in ntit.split() if len(x)>3][:8]
  author_tokens=[x for x in norm(author).split() if len(x)>3]
  title_hits=sum(t in nt for t in title_tokens); author_hits=sum(t in nt for t in author_tokens)
  # DOI/landing records can be HTML with metadata; require strong title + author evidence.
  ipass=(title_hits>=max(2,min(4,len(title_tokens))) and author_hits>=1) or (pid=='S24P08' and ('openiti' in nt and 'islamicate' in nt))
  identities.append({**base,'file':str(path.relative_to(RUN)),'title_token_hits':title_hits,'author_token_hits':author_hits,'identity_pass':bool(ipass),'identity_note':'content match' if ipass else 'mismatch or insufficient metadata'})
  downloads.append({**base,'status':'downloaded','file':str(path.relative_to(RUN)),'sha256':sha,'bytes':len(data),'content_type':ct or mimetypes.guess_type(str(path))[0] or 'application/octet-stream'})
  if not ipass: blocked.append({**base,'reason':'identity_mismatch_or_insufficient_metadata','file':str(path.relative_to(RUN))})
 else:
  identities.append({**base,'file':'','title_token_hits':0,'author_token_hits':0,'identity_pass':False,'identity_note':'inaccessible'})
  blocked.append({**base,'reason':'inaccessible','error':err})
  downloads.append({**base,'status':'failed','error':err})
